INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-grammar-b2-01-01', 'lesson-grammar-b2-01', 1, 'sentence', 'I wish I had more time.', 'Queria ter mais tempo.', '/aɪ wɪʃ aɪ hæd mɔːr taɪm/', '"Wish" + passado simples = desejo sobre o presente que não é real.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-02', 'lesson-grammar-b2-01', 2, 'sentence', 'I wish I lived closer to the beach.', 'Queria morar mais perto da praia.', '/aɪ wɪʃ aɪ lɪvd ˈkloʊsər tuː ðə biːtʃ/', 'O verbo vai ao passado (lived), mas o assunto é agora.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"},{"surface":"closer","pos":"adverb","ipa":"/ˈkloʊsər/","gloss":"mais perto"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"beach","pos":"noun","ipa":"/biːtʃ/","gloss":"praia"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-03', 'lesson-grammar-b2-01', 3, 'sentence', 'If only I knew the answer.', 'Se ao menos eu soubesse a resposta.', '/ɪf ˈoʊnli aɪ nuː ðə ˈænsər/', '"If only" é um "wish" mais forte e mais emotivo.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"knew","pos":"verb","ipa":"/nuː/","gloss":"sabia, conheceu"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-04', 'lesson-grammar-b2-01', 4, 'sentence', 'I wish I had studied harder.', 'Queria ter estudado mais.', '/aɪ wɪʃ aɪ hæd ˈstʌdid ˈhɑːrdər/', '"Wish" + past perfect = arrependimento sobre o passado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"studied","pos":"verb","ipa":"/ˈstʌdid/","gloss":"estudou, estudado"},{"surface":"harder","pos":"adjective","ipa":"/ˈhɑːrdər/","gloss":"mais difícil"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-05', 'lesson-grammar-b2-01', 5, 'sentence', 'She wishes she had never told him.', 'Ela queria nunca ter contado a ele.', '/ʃiː ˈwɪʃɪz ʃiː hæd ˈnɛvər toʊld hɪm/', 'Com "she", "wishes" leva s; a segunda parte segue no past perfect.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"wishes","pos":"verb","ipa":"/ˈwɪʃɪz/","gloss":"deseja"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"him","pos":"pronoun","ipa":"/hɪm/","gloss":"ele, o, lhe"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-06', 'lesson-grammar-b2-01', 6, 'sentence', 'If only we had left earlier.', 'Se ao menos a gente tivesse saído mais cedo.', '/ɪf ˈoʊnli wiː hæd lɛft ˈɜːrliər/', '"If only" + past perfect = lamento por algo que já passou.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"earlier","pos":"adverb","ipa":"/ˈɜːrliər/","gloss":"mais cedo, antes"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-07', 'lesson-grammar-b2-01', 7, 'sentence', 'I wish it would stop raining.', 'Queria que parasse de chover.', '/aɪ wɪʃ ɪt wʊd stɑːp ˈreɪnɪŋ/', '"Wish" + would = reclamar do que incomoda e desejar que mude.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"stop","pos":"verb","ipa":"/stɑːp/","gloss":"parar"},{"surface":"raining","pos":"verb","ipa":"/ˈreɪnɪŋ/","gloss":"chovendo"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-08', 'lesson-grammar-b2-01', 8, 'sentence', 'I wish you would listen to me.', 'Queria que você me ouvisse.', '/aɪ wɪʃ juː wʊd ˈlɪsən tuː miː/', '"Wish + would" pede mudança de comportamento do outro; não se usa com "I".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"listen","pos":"verb","ipa":"/ˈlɪsən/","gloss":"escutar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-09', 'lesson-grammar-b2-01', 9, 'sentence', 'I wish I were taller.', 'Queria ser mais alto.', '/aɪ wɪʃ aɪ wɜːr ˈtɔːlər/', 'Depois de "wish", "were" vale para todas as pessoas; "was" aparece na fala informal.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"taller","pos":"adjective","ipa":"/ˈtɔːlər/","gloss":"mais alto"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-01-10', 'lesson-grammar-b2-01', 10, 'sentence', 'He acts as if he owned the place.', 'Ele age como se fosse o dono do lugar.', '/hiː ækts æz ɪf hiː oʊnd ðə pleɪs/', '"As if" + passado simples = situação irreal no presente.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"acts","pos":"verb","ipa":"/ækts/","gloss":"age, se comporta"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"owned","pos":"verb","ipa":"/oʊnd/","gloss":"fosse dono de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"place","pos":"noun","ipa":"/pleɪs/","gloss":"lugar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-grammar-b2-02-01', 'lesson-grammar-b2-02', 1, 'sentence', 'If I had saved more, I would be richer now.', 'Se eu tivesse economizado mais, seria mais rico agora.', '/ɪf aɪ hæd seɪvd mɔːr aɪ wʊd biː ˈrɪtʃər naʊ/', 'Misto: past perfect no "if" e would + verbo no resultado, que é o presente.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"saved","pos":"verb","ipa":"/seɪvd/","gloss":"salvou"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"richer","pos":"adjective","ipa":"/ˈrɪtʃər/","gloss":"mais rico"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-02', 'lesson-grammar-b2-02', 2, 'sentence', 'If she had taken the job, she would live in Paris now.', 'Se ela tivesse aceitado o emprego, moraria em Paris agora.', '/ɪf ʃiː hæd ˈteɪkən ðə dʒɑːb ʃiː wʊd lɪv ɪn ˈpærɪs naʊ/', 'Uma escolha do passado que ainda muda a vida de hoje.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"taken","pos":"verb","ipa":"/ˈteɪkən/","gloss":"pegado, levado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"Paris","pos":"proper noun","ipa":"/ˈpærɪs/","gloss":"Paris"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-03', 'lesson-grammar-b2-02', 3, 'sentence', 'If I were you, I would have called him.', 'Se eu fosse você, teria ligado para ele.', '/ɪf aɪ wɜːr juː aɪ wʊd hæv kɔːld hɪm/', 'Misto invertido: presente no "if" e passado no resultado.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"him","pos":"pronoun","ipa":"/hɪm/","gloss":"ele, o, lhe"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-04', 'lesson-grammar-b2-02', 4, 'sentence', 'If he were more careful, he would not have lost his keys.', 'Se ele fosse mais cuidadoso, não teria perdido as chaves.', '/ɪf hiː wɜːr mɔːr ˈkɛrfəl hiː wʊd nɑːt hæv lɔːst hɪz kiːz/', 'Uma característica de hoje explica o que aconteceu.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"careful","pos":"adjective","ipa":"/ˈkɛrfəl/","gloss":"cuidadoso"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"his","pos":"determiner","ipa":"/hɪz/","gloss":"dele"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-05', 'lesson-grammar-b2-02', 5, 'sentence', 'If we had booked earlier, we would not be standing in this line.', 'Se tivéssemos reservado antes, não estaríamos nesta fila.', '/ɪf wiː hæd bʊkt ˈɜːrliər wiː wʊd nɑːt biː ˈstændɪŋ ɪn ðɪs laɪn/', '"Would not be" + ing descreve a situação de agora.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"booked","pos":"adjective","ipa":"/bʊkt/","gloss":"reservado, lotado"},{"surface":"earlier","pos":"adverb","ipa":"/ˈɜːrliər/","gloss":"mais cedo, antes"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"standing","pos":"verb","ipa":"/ˈstændɪŋ/","gloss":"em pé"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"line","pos":"noun","ipa":"/laɪn/","gloss":"linha"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-06', 'lesson-grammar-b2-02', 6, 'sentence', 'If you had listened, you would know what to do.', 'Se você tivesse ouvido, saberia o que fazer.', '/ɪf juː hæd ˈlɪsənd juː wʊd noʊ wʌt tuː duː/', 'O resultado é no presente porque a atitude do passado não aconteceu.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"listened","pos":"verb","ipa":"/ˈlɪsənd/","gloss":"ouviu"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-07', 'lesson-grammar-b2-02', 7, 'sentence', 'I would be fluent by now if I had practiced every day.', 'Eu já estaria fluente se tivesse praticado todo dia.', '/aɪ wʊd biː ˈfluːənt baɪ naʊ ɪf aɪ hæd ˈpræktɪst ˈɛvri deɪ/', 'A ordem das partes pode inverter; o sentido é o mesmo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"fluent","pos":"adjective","ipa":"/ˈfluːənt/","gloss":"fluente"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"practiced","pos":"verb","ipa":"/ˈpræktɪst/","gloss":"praticado"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-08', 'lesson-grammar-b2-02', 8, 'sentence', 'If I weren''t so tired, I would have gone to the party.', 'Se eu não estivesse tão cansado, teria ido à festa.', '/ɪf aɪ wɜːrnt soʊ ˈtaɪərd aɪ wʊd hæv ɡɔːn tuː ðə ˈpɑːrti/', '"Weren''t" com "I" é a forma de "if" irreal.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"weren''t","pos":"verb","ipa":"/wɜːrnt/","gloss":"não eram, não estavam (were not)"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"gone","pos":"verb","ipa":"/ɡɔːn/","gloss":"ido (particípio de go)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"party","pos":"noun","ipa":"/ˈpɑːrti/","gloss":"festa"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-09', 'lesson-grammar-b2-02', 9, 'sentence', 'If they had won, they would be champions today.', 'Se eles tivessem ganhado, seriam campeões hoje.', '/ɪf ðeɪ hæd wʌn ðeɪ wʊd biː ˈtʃæmpiənz təˈdeɪ/', 'Past perfect no "if" e would + verbo no resultado.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"won","pos":"verb","ipa":"/wʌn/","gloss":"ganhou"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"champions","pos":"noun","ipa":"/ˈtʃæmpiənz/","gloss":"campeões"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-02-10', 'lesson-grammar-b2-02', 10, 'sentence', 'We would still be friends if she had not moved away.', 'Ainda seríamos amigos se ela não tivesse se mudado.', '/wiː wʊd stɪl biː frɛndz ɪf ʃiː hæd nɑːt muːvd əˈweɪ/', '"Still" reforça que a situação continuaria até hoje.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"still","pos":"adverb","ipa":"/stɪl/","gloss":"ainda"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"moved","pos":"verb","ipa":"/muːvd/","gloss":"mudou-se, moveu"},{"surface":"away","pos":"adverb","ipa":"/əˈweɪ/","gloss":"embora; (right away) já"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-grammar-b2-03-01', 'lesson-grammar-b2-03', 1, 'sentence', 'I had my car repaired yesterday.', 'Mandei consertar meu carro ontem.', '/aɪ hæd maɪ kɑːr rɪˈpɛrd ˈjɛstərdeɪ/', '"Have + objeto + particípio" = mandar fazer; quem faz o serviço não aparece.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"repaired","pos":"verb","ipa":"/rɪˈpɛrd/","gloss":"consertado"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-02', 'lesson-grammar-b2-03', 2, 'sentence', 'She is having her hair cut tomorrow.', 'Ela vai cortar o cabelo amanhã.', '/ʃiː ɪz ˈhævɪŋ hɜːr hɛr kʌt təˈmɑːroʊ/', 'No contínuo, o futuro é marcado por "tomorrow"; alguém corta, não ela.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"having","pos":"verb","ipa":"/ˈhævɪŋ/","gloss":"receber, ter"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"hair","pos":"noun","ipa":"/hɛr/","gloss":"cabelo"},{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-03', 'lesson-grammar-b2-03', 3, 'sentence', 'We need to get the roof fixed.', 'Precisamos mandar arrumar o telhado.', '/wiː niːd tuː ɡɛt ðə ruːf fɪkst/', '"Get + objeto + particípio" é mais informal que "have".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"roof","pos":"noun","ipa":"/ruːf/","gloss":"telhado"},{"surface":"fixed","pos":"verb","ipa":"/fɪkst/","gloss":"consertado"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-04', 'lesson-grammar-b2-03', 4, 'sentence', 'He had his phone stolen on the train.', 'Roubaram o celular dele no trem.', '/hiː hæd hɪz foʊn ˈstoʊlən ɑːn ðə treɪn/', 'O causativo também mostra algo ruim que acontece sem querer.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"his","pos":"determiner","ipa":"/hɪz/","gloss":"dele"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"stolen","pos":"verb","ipa":"/ˈstoʊlən/","gloss":"roubado"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-05', 'lesson-grammar-b2-03', 5, 'sentence', 'I will have the report ready by Friday.', 'Vou deixar o relatório pronto até sexta.', '/aɪ wɪl hæv ðə rɪˈpɔːrt ˈrɛdi baɪ ˈfraɪdeɪ/', '"Have + objeto + adjetivo" = deixar em certo estado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"ready","pos":"adjective","ipa":"/ˈrɛdi/","gloss":"pronto"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"Friday","pos":"proper noun","ipa":"/ˈfraɪdeɪ/","gloss":"sexta-feira"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-06', 'lesson-grammar-b2-03', 6, 'sentence', 'She had the waiter bring another menu.', 'Ela pediu para o garçom trazer outro cardápio.', '/ʃiː hæd ðə ˈweɪtər brɪŋ əˈnʌðər ˈmɛnjuː/', '"Have + pessoa + verbo simples", sem "to" = fazer alguém fazer.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"waiter","pos":"noun","ipa":"/ˈweɪtər/","gloss":"garçom"},{"surface":"bring","pos":"verb","ipa":"/brɪŋ/","gloss":"trazer"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"menu","pos":"noun","ipa":"/ˈmɛnjuː/","gloss":"cardápio"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-07', 'lesson-grammar-b2-03', 7, 'sentence', 'I got my brother to help me move.', 'Convenci meu irmão a me ajudar na mudança.', '/aɪ ɡɑːt maɪ ˈbrʌðər tuː hɛlp miː muːv/', '"Get + pessoa + to + verbo" = convencer alguém a fazer.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"move","pos":"verb","ipa":"/muːv/","gloss":"mover, passar"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-08', 'lesson-grammar-b2-03', 8, 'sentence', 'Where do you get your nails done?', 'Onde você faz as unhas?', '/wɛr duː juː ɡɛt jʊr neɪlz dʌn/', 'Pergunta comum: a pessoa paga por um serviço.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"nails","pos":"noun","ipa":"/neɪlz/","gloss":"unhas"},{"surface":"done","pos":"adjective","ipa":"/dʌn/","gloss":"pronto, feito"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-09', 'lesson-grammar-b2-03', 9, 'sentence', 'They had the whole kitchen painted.', 'Eles mandaram pintar a cozinha inteira.', '/ðeɪ hæd ðə hoʊl ˈkɪtʃən ˈpeɪntɪd/', 'O particípio descreve o que aconteceu com o objeto, não quem pintou.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"whole","pos":"adjective","ipa":"/hoʊl/","gloss":"inteiro"},{"surface":"kitchen","pos":"noun","ipa":"/ˈkɪtʃən/","gloss":"cozinha"},{"surface":"painted","pos":"verb","ipa":"/ˈpeɪntɪd/","gloss":"pintado"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-03-10', 'lesson-grammar-b2-03', 10, 'sentence', 'Have you had your eyes checked lately?', 'Você fez um exame de vista ultimamente?', '/hæv juː hæd jʊr aɪz tʃɛkt ˈleɪtli/', 'Present perfect + causativo: o segundo "had" é o particípio de "have".', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"eyes","pos":"noun","ipa":"/aɪz/","gloss":"olhos"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"lately","pos":"adverb","ipa":"/ˈleɪtli/","gloss":"ultimamente"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-grammar-b2-04-01', 'lesson-grammar-b2-04', 1, 'sentence', 'The man who lives next door is a doctor.', 'O homem que mora ao lado é médico.', '/ðə mæn huː lɪvz nɛkst dɔːr ɪz ə ˈdɑːktər/', '"Who" se refere a pessoa e aqui é o sujeito da oração.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"man","pos":"noun","ipa":"/mæn/","gloss":"homem"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"lives","pos":"verb","ipa":"/lɪvz/","gloss":"mora, vive"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"doctor","pos":"noun","ipa":"/ˈdɑːktər/","gloss":"médico"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-02', 'lesson-grammar-b2-04', 2, 'sentence', 'This is the book that I told you about.', 'Este é o livro de que te falei.', '/ðɪs ɪz ðə bʊk ðæt aɪ toʊld juː əˈbaʊt/', '"That" pode sumir quando é objeto: "the book I told you about".', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-03', 'lesson-grammar-b2-04', 3, 'sentence', 'The woman whose car was stolen called the police.', 'A mulher cujo carro foi roubado chamou a polícia.', '/ðə ˈwʊmən huːz kɑːr wɑːz ˈstoʊlən kɔːld ðə pəˈliːs/', '"Whose" = cujo; liga a posse sem usar artigo depois.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"woman","pos":"noun","ipa":"/ˈwʊmən/","gloss":"mulher"},{"surface":"whose","pos":"pronoun","ipa":"/huːz/","gloss":"de quem"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"stolen","pos":"verb","ipa":"/ˈstoʊlən/","gloss":"roubado"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"police","pos":"noun","ipa":"/pəˈliːs/","gloss":"polícia"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-04', 'lesson-grammar-b2-04', 4, 'sentence', 'That is the restaurant where we first met.', 'Aquele é o restaurante onde nos conhecemos.', '/ðæt ɪz ðə ˈrɛstərɑːnt wɛr wiː fɜːrst mɛt/', '"Where" substitui "in which" quando se fala de lugar.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"restaurant","pos":"noun","ipa":"/ˈrɛstərɑːnt/","gloss":"restaurante"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"met","pos":"verb","ipa":"/mɛt/","gloss":"conheceu, encontrou"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-05', 'lesson-grammar-b2-04', 5, 'sentence', 'My brother, who lives in Canada, is visiting us.', 'Meu irmão, que mora no Canadá, vem nos visitar.', '/maɪ ˈbrʌðər huː lɪvz ɪn ˈkænədə ɪz ˈvɪzɪtɪŋ ʌs/', 'Entre vírgulas, é informação extra: "that" não vale nesse caso.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"lives","pos":"verb","ipa":"/lɪvz/","gloss":"mora, vive"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"Canada","pos":"proper noun","ipa":"/ˈkænədə/","gloss":"Canadá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"visiting","pos":"adjective","ipa":"/ˈvɪzɪtɪŋ/","gloss":"de visita"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-06', 'lesson-grammar-b2-04', 6, 'sentence', 'She is the person I was telling you about.', 'Ela é a pessoa de quem eu estava falando.', '/ʃiː ɪz ðə ˈpɜːrsən aɪ wɑːz ˈtɛlɪŋ juː əˈbaʊt/', 'Pronome omitido; na fala natural a preposição fica no fim.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"person","pos":"noun","ipa":"/ˈpɜːrsən/","gloss":"pessoa"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"telling","pos":"verb","ipa":"/ˈtɛlɪŋ/","gloss":"contando"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-07', 'lesson-grammar-b2-04', 7, 'sentence', 'I remember the day when we moved here.', 'Lembro do dia em que nos mudamos para cá.', '/aɪ rɪˈmɛmbər ðə deɪ wɛn wiː muːvd hɪr/', '"When" depois de substantivo de tempo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"moved","pos":"verb","ipa":"/muːvd/","gloss":"mudou-se, moveu"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-08', 'lesson-grammar-b2-04', 8, 'sentence', 'Everything that he said was true.', 'Tudo o que ele disse era verdade.', '/ˈɛvriθɪŋ ðæt hiː sɛd wɑːz truː/', 'Depois de "everything", "all" e "something" usa-se "that", não "what".', '[]'::jsonb, '[{"surface":"Everything","pos":"pronoun","ipa":"/ˈɛvriθɪŋ/","gloss":"tudo"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"true","pos":"adjective","ipa":"/truː/","gloss":"verdadeiro"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-09', 'lesson-grammar-b2-04', 9, 'sentence', 'The meeting, which lasted three hours, ended late.', 'A reunião, que durou três horas, terminou tarde.', '/ðə ˈmiːtɪŋ wɪtʃ ˈlæstɪd θriː aʊərz ˈɛndɪd leɪt/', '"Which" com vírgulas para coisas: acrescenta um dado.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"lasted","pos":"verb","ipa":"/ˈlæstɪd/","gloss":"durou"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"hours","pos":"noun","ipa":"/aʊərz/","gloss":"horas"},{"surface":"ended","pos":"verb","ipa":"/ˈɛndɪd/","gloss":"terminou"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-04-10', 'lesson-grammar-b2-04', 10, 'sentence', 'People who work from home save time.', 'Pessoas que trabalham em casa economizam tempo.', '/ˈpiːpəl huː wɜːrk frʌm hoʊm seɪv taɪm/', 'Sem vírgulas, define de quais pessoas se fala.', '[]'::jsonb, '[{"surface":"People","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"save","pos":"verb","ipa":"/seɪv/","gloss":"economizar, salvar"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-grammar-b2-05-01', 'lesson-grammar-b2-05', 1, 'sentence', 'I enjoy cooking for my friends.', 'Gosto de cozinhar para meus amigos.', '/aɪ ɪnˈdʒɔɪ ˈkʊkɪŋ fɔːr maɪ frɛndz/', '"Enjoy" é seguido de verbo com -ing.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"enjoy","pos":"verb","ipa":"/ɪnˈdʒɔɪ/","gloss":"aproveitar"},{"surface":"cooking","pos":"verb","ipa":"/ˈkʊkɪŋ/","gloss":"cozinhar (atividade)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-02', 'lesson-grammar-b2-05', 2, 'sentence', 'She decided to quit her job.', 'Ela decidiu largar o emprego.', '/ʃiː dɪˈsaɪdɪd tuː kwɪt hɜːr dʒɑːb/', '"Decide" pede infinitivo com "to".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"decided","pos":"verb","ipa":"/dɪˈsaɪdɪd/","gloss":"decidiu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"quit","pos":"verb","ipa":"/kwɪt/","gloss":"parar, largar"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-03', 'lesson-grammar-b2-05', 3, 'sentence', 'He avoids eating late at night.', 'Ele evita comer tarde da noite.', '/hiː əˈvɔɪdz ˈiːtɪŋ leɪt æt naɪt/', '"Avoid" também pede -ing.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"avoids","pos":"verb","ipa":"/əˈvɔɪdz/","gloss":"evita"},{"surface":"eating","pos":"verb","ipa":"/ˈiːtɪŋ/","gloss":"comendo"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-04', 'lesson-grammar-b2-05', 4, 'sentence', 'We hope to see you again soon.', 'Esperamos ver você de novo em breve.', '/wiː hoʊp tuː siː juː əˈɡɛn suːn/', '"Hope" pede infinitivo com "to".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"hope","pos":"verb","ipa":"/hoʊp/","gloss":"esperar (ter esperança)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-05', 'lesson-grammar-b2-05', 5, 'sentence', 'I stopped smoking two years ago.', 'Parei de fumar há dois anos.', '/aɪ stɑːpt ˈsmoʊkɪŋ tuː jɪrz əˈɡoʊ/', '"Stop" + -ing = parar de fazer.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"stopped","pos":"verb","ipa":"/stɑːpt/","gloss":"parou"},{"surface":"smoking","pos":"noun","ipa":"/ˈsmoʊkɪŋ/","gloss":"fumar, o hábito de fumar"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"ago","pos":"adverb","ipa":"/əˈɡoʊ/","gloss":"atrás (tempo)"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-06', 'lesson-grammar-b2-05', 6, 'sentence', 'I stopped to buy some water.', 'Parei para comprar água.', '/aɪ stɑːpt tuː baɪ sʌm ˈwɔːtər/', '"Stop" + to = parar uma coisa para fazer outra.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"stopped","pos":"verb","ipa":"/stɑːpt/","gloss":"parou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-07', 'lesson-grammar-b2-05', 7, 'sentence', 'I remember locking the door.', 'Lembro de ter trancado a porta.', '/aɪ rɪˈmɛmbər ˈlɑːkɪŋ ðə dɔːr/', '"Remember" + -ing = lembrar de algo que já foi feito.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"locking","pos":"verb","ipa":"/ˈlɑːkɪŋ/","gloss":"trancando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-08', 'lesson-grammar-b2-05', 8, 'sentence', 'Remember to lock the door.', 'Lembre de trancar a porta.', '/rɪˈmɛmbər tuː lɑːk ðə dɔːr/', '"Remember" + to = não esquecer de fazer.', '[]'::jsonb, '[{"surface":"Remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"lock","pos":"verb","ipa":"/lɑːk/","gloss":"trancar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-09', 'lesson-grammar-b2-05', 9, 'sentence', 'She tried to open the window, but it was stuck.', 'Ela tentou abrir a janela, mas estava emperrada.', '/ʃiː traɪd tuː ˈoʊpən ðə ˈwɪndoʊ bʌt ɪt wɑːz stʌk/', '"Try" + to = tentar, fazer esforço.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"tried","pos":"verb","ipa":"/traɪd/","gloss":"tentou, experimentou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"window","pos":"noun","ipa":"/ˈwɪndoʊ/","gloss":"janela"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"stuck","pos":"adjective","ipa":"/stʌk/","gloss":"preso"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-05-10', 'lesson-grammar-b2-05', 10, 'sentence', 'Try adding a little salt.', 'Experimente colocar um pouco de sal.', '/traɪ ˈædɪŋ ə ˈlɪtəl sɔːlt/', '"Try" + -ing = experimentar para ver o resultado.', '[]'::jsonb, '[{"surface":"Try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"adding","pos":"verb","ipa":"/ˈædɪŋ/","gloss":"acrescentando"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"salt","pos":"noun","ipa":"/sɔːlt/","gloss":"sal"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-grammar-b2-06-01', 'lesson-grammar-b2-06', 1, 'sentence', 'It was Mark who broke the window.', 'Foi o Mark que quebrou a janela.', '/ɪt wɑːz mɑːrk huː broʊk ðə ˈwɪndoʊ/', '"It was ... who" destaca o sujeito.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"Mark","pos":"noun","ipa":"/mɑːrk/","gloss":"Mark (nome próprio)"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"window","pos":"noun","ipa":"/ˈwɪndoʊ/","gloss":"janela"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-02', 'lesson-grammar-b2-06', 2, 'sentence', 'It is the price that worries me.', 'É o preço que me preocupa.', '/ɪt ɪz ðə praɪs ðæt ˈwɜːriz miː/', 'Estrutura de destaque com "that".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"price","pos":"noun","ipa":"/praɪs/","gloss":"preço"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"worries","pos":"noun","ipa":"/ˈwɜːriz/","gloss":"preocupações"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-03', 'lesson-grammar-b2-06', 3, 'sentence', 'What I need is a long vacation.', 'O que eu preciso é de umas férias longas.', '/wʌt aɪ niːd ɪz ə lɔːŋ veɪˈkeɪʃən/', '"What I need is" destaca o objeto da frase.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"vacation","pos":"noun","ipa":"/veɪˈkeɪʃən/","gloss":"férias"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-04', 'lesson-grammar-b2-06', 4, 'sentence', 'What surprised me was her honesty.', 'O que me surpreendeu foi a honestidade dela.', '/wʌt sərˈpraɪzd miː wɑːz hɜːr ˈɑːnəsti/', '"What" faz o papel de sujeito da oração destacada.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"surprised","pos":"adjective","ipa":"/sərˈpraɪzd/","gloss":"surpreso"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"honesty","pos":"noun","ipa":"/ˈɑːnəsti/","gloss":"honestidade"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-05', 'lesson-grammar-b2-06', 5, 'sentence', 'All I want is a quiet evening.', 'Tudo o que eu quero é uma noite tranquila.', '/ɔːl aɪ wɑːnt ɪz ə ˈkwaɪət ˈiːvnɪŋ/', '"All" com o sentido de "a única coisa".', '[]'::jsonb, '[{"surface":"All","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"quiet","pos":"adjective","ipa":"/ˈkwaɪət/","gloss":"quieto"},{"surface":"evening","pos":"noun","ipa":"/ˈiːvnɪŋ/","gloss":"noite (início), fim de tarde"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-06', 'lesson-grammar-b2-06', 6, 'sentence', 'I did call you, but you did not answer.', 'Eu liguei sim, mas você não atendeu.', '/aɪ dɪd kɔːl juː bʌt juː dɪd nɑːt ˈænsər/', '"Did" antes do verbo reforça a afirmação.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-07', 'lesson-grammar-b2-06', 7, 'sentence', 'She does love her job.', 'Ela adora mesmo o trabalho dela.', '/ʃiː dʌz lʌv hɜːr dʒɑːb/', '"Does" + verbo base reforça; o verbo não leva s.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"love","pos":"verb","ipa":"/lʌv/","gloss":"amar, adorar"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-08', 'lesson-grammar-b2-06', 8, 'sentence', 'It was not until midnight that we got home.', 'Só à meia-noite chegamos em casa.', '/ɪt wɑːz nɑːt ənˈtɪl ˈmɪdnaɪt ðæt wiː ɡɑːt hoʊm/', '"Not until" no início dá destaque ao momento.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"midnight","pos":"noun","ipa":"/ˈmɪdnaɪt/","gloss":"meia-noite"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-09', 'lesson-grammar-b2-06', 9, 'sentence', 'The thing that I like most is the food.', 'O que eu mais gosto é da comida.', '/ðə θɪŋ ðæt aɪ laɪk moʊst ɪz ðə fuːd/', '"The thing that" = alternativa a "what".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"thing","pos":"noun","ipa":"/θɪŋ/","gloss":"coisa"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"food","pos":"noun","ipa":"/fuːd/","gloss":"comida"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-06-10', 'lesson-grammar-b2-06', 10, 'sentence', 'It is exactly what I was hoping for.', 'É exatamente o que eu esperava.', '/ɪt ɪz ɪɡˈzæktli wʌt aɪ wɑːz ˈhoʊpɪŋ fɔːr/', '"Exactly" reforça a ideia de coincidência.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"exactly","pos":"adverb","ipa":"/ɪɡˈzæktli/","gloss":"exatamente"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"hoping","pos":"verb","ipa":"/ˈhoʊpɪŋ/","gloss":"esperando, torcendo"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-grammar-b2-07-01', 'lesson-grammar-b2-07', 1, 'sentence', 'Never have I seen such a mess.', 'Nunca vi uma bagunça assim.', '/ˈnɛvər hæv aɪ siːn sʌtʃ ə mɛs/', 'Advérbio negativo no início exige auxiliar + sujeito.', '[]'::jsonb, '[{"surface":"Never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"seen","pos":"verb","ipa":"/siːn/","gloss":"visto"},{"surface":"such","pos":"determiner","ipa":"/sʌtʃ/","gloss":"tal, tão"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"mess","pos":"noun","ipa":"/mɛs/","gloss":"bagunça"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-02', 'lesson-grammar-b2-07', 2, 'sentence', 'Rarely does he complain about anything.', 'Raramente ele reclama de qualquer coisa.', '/ˈrɛrli dʌz hiː kəmˈpleɪn əˈbaʊt ˈɛniθɪŋ/', '"Rarely" + does he; o verbo volta à forma base.', '[]'::jsonb, '[{"surface":"Rarely","pos":"adverb","ipa":"/ˈrɛrli/","gloss":"raramente"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"complain","pos":"verb","ipa":"/kəmˈpleɪn/","gloss":"reclamar"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"anything","pos":"pronoun","ipa":"/ˈɛniθɪŋ/","gloss":"algo, alguma coisa"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-03', 'lesson-grammar-b2-07', 3, 'sentence', 'Not only did she win, but she also broke the record.', 'Ela não só ganhou como também quebrou o recorde.', '/nɑːt ˈoʊnli dɪd ʃiː wɪn bʌt ʃiː ˈɔːlsoʊ broʊk ðə ˈrɛkərd/', '"Not only" no início inverte a primeira parte.', '[]'::jsonb, '[{"surface":"Not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"win","pos":"noun","ipa":"/wɪn/","gloss":"vitória, conquista"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"record","pos":"noun","ipa":"/ˈrɛkərd/","gloss":"recorde"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-04', 'lesson-grammar-b2-07', 4, 'sentence', 'Hardly had we arrived when it started to rain.', 'Mal tínhamos chegado quando começou a chover.', '/ˈhɑːrdli hæd wiː əˈraɪvd wɛn ɪt ˈstɑːrtɪd tuː reɪn/', '"Hardly" + past perfect invertido, ligado por "when".', '[]'::jsonb, '[{"surface":"Hardly","pos":"adverb","ipa":"/ˈhɑːrdli/","gloss":"mal, quase não"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-05', 'lesson-grammar-b2-07', 5, 'sentence', 'Under no circumstances should you open this door.', 'Em hipótese alguma você deve abrir esta porta.', '/ˈʌndər noʊ ˈsɜːrkəmstænsɪz ʃʊd juː ˈoʊpən ðɪs dɔːr/', 'Expressões negativas no início invertem com "should".', '[]'::jsonb, '[{"surface":"Under","pos":"preposition","ipa":"/ˈʌndər/","gloss":"no nome de, sob"},{"surface":"no","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"circumstances","pos":"noun","ipa":"/ˈsɜːrkəmstænsɪz/","gloss":"circunstâncias"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-06', 'lesson-grammar-b2-07', 6, 'sentence', 'Only then did I understand the problem.', 'Só então entendi o problema.', '/ˈoʊnli ðɛn dɪd aɪ ˌʌndərˈstænd ðə ˈprɑːbləm/', '"Only then" também inverte.', '[]'::jsonb, '[{"surface":"Only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"understand","pos":"verb","ipa":"/ˌʌndərˈstænd/","gloss":"entender"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-07', 'lesson-grammar-b2-07', 7, 'sentence', 'Little did they know about the surprise.', 'Eles nem imaginavam a surpresa.', '/ˈlɪtəl dɪd ðeɪ noʊ əˈbaʊt ðə sərˈpraɪz/', '"Little did" = não sabiam nada; estilo formal ou de narrativa.', '[]'::jsonb, '[{"surface":"Little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"surprise","pos":"noun","ipa":"/sərˈpraɪz/","gloss":"surpresa"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-08', 'lesson-grammar-b2-07', 8, 'sentence', 'Had I known, I would have helped.', 'Se eu soubesse, teria ajudado.', '/hæd aɪ noʊn aɪ wʊd hæv hɛlpt/', 'Inversão sem "if" na terceira condicional; tom formal.', '[]'::jsonb, '[{"surface":"Had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"known","pos":"verb","ipa":"/noʊn/","gloss":"sabido, conhecido"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-09', 'lesson-grammar-b2-07', 9, 'sentence', 'Should you need anything, please call me.', 'Se precisar de algo, me ligue.', '/ʃʊd juː niːd ˈɛniθɪŋ pliːz kɔːl miː/', '"Should" invertido = "if you should"; formal e muito usado em e-mails.', '[]'::jsonb, '[{"surface":"Should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"anything","pos":"pronoun","ipa":"/ˈɛniθɪŋ/","gloss":"algo, alguma coisa"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-07-10', 'lesson-grammar-b2-07', 10, 'sentence', 'No sooner had he sat down than the phone rang.', 'Mal ele sentou e o telefone tocou.', '/noʊ ˈsuːnər hæd hiː sæt daʊn ðæn ðə foʊn ræŋ/', '"No sooner ... than" liga dois acontecimentos em seguida.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"sooner","pos":"adverb","ipa":"/ˈsuːnər/","gloss":"mais cedo"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"sat","pos":"verb","ipa":"/sæt/","gloss":"sentou"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"rang","pos":"verb","ipa":"/ræŋ/","gloss":"tocou (telefone)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-grammar-b2-08-01', 'lesson-grammar-b2-08', 1, 'sentence', 'By next year, I will have finished my degree.', 'Até o ano que vem, terei terminado a faculdade.', '/baɪ nɛkst jɪr aɪ wɪl hæv ˈfɪnɪʃt maɪ dɪˈɡriː/', 'Future perfect: algo concluído antes de um ponto no futuro.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"degree","pos":"noun","ipa":"/dɪˈɡriː/","gloss":"diploma, graduação"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-02', 'lesson-grammar-b2-08', 2, 'sentence', 'She will have left by the time we arrive.', 'Ela já terá saído quando a gente chegar.', '/ʃiː wɪl hæv lɛft baɪ ðə taɪm wiː əˈraɪv/', 'Depois de "by the time" vem o presente simples; o verbo principal fica no future perfect.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-03', 'lesson-grammar-b2-08', 3, 'sentence', 'By June, we will have lived here for five years.', 'Em junho, vamos completar cinco anos morando aqui.', '/baɪ dʒuːn wiː wɪl hæv lɪvd hɪr fɔːr faɪv jɪrz/', 'Future perfect com duração: "for" + período.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"June","pos":"proper noun","ipa":"/dʒuːn/","gloss":"junho"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-04', 'lesson-grammar-b2-08', 4, 'sentence', 'This time tomorrow, I will be flying to Rome.', 'Amanhã a esta hora, estarei voando para Roma.', '/ðɪs taɪm təˈmɑːroʊ aɪ wɪl biː ˈflaɪɪŋ tuː roʊm/', 'Future continuous: ação em andamento num momento futuro.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"flying","pos":"verb","ipa":"/ˈflaɪɪŋ/","gloss":"voando"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Rome","pos":"proper noun","ipa":"/roʊm/","gloss":"Roma"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-05', 'lesson-grammar-b2-08', 5, 'sentence', 'Don''t call at eight, we will be having dinner.', 'Não ligue às oito, estaremos jantando.', '/doʊnt kɔːl æt eɪt wiː wɪl biː ˈhævɪŋ ˈdɪnər/', '"Will be" + -ing avisa que a pessoa estará ocupada.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"having","pos":"verb","ipa":"/ˈhævɪŋ/","gloss":"receber, ter"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-06', 'lesson-grammar-b2-08', 6, 'sentence', 'Will you be using the car tonight?', 'Você vai usar o carro hoje à noite?', '/wɪl juː biː ˈjuːzɪŋ ðə kɑːr təˈnaɪt/', 'Pergunta educada sobre planos, mais suave que "are you going to".', '[]'::jsonb, '[{"surface":"Will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"using","pos":"verb","ipa":"/ˈjuːzɪŋ/","gloss":"usando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-07', 'lesson-grammar-b2-08', 7, 'sentence', 'By the end of the week, they will have been working on it for a month.', 'Até o fim da semana, eles estarão há um mês trabalhando nisso.', '/baɪ ðə ɛnd ʌv ðə wiːk ðeɪ wɪl hæv bɪn ˈwɜːrkɪŋ ɑːn ɪt fɔːr ə mʌnθ/', 'Future perfect continuous: duração acumulada até um ponto futuro.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-08', 'lesson-grammar-b2-08', 8, 'sentence', 'I will have been waiting for an hour by then.', 'Eu já estarei esperando há uma hora até lá.', '/aɪ wɪl hæv bɪn ˈweɪtɪŋ fɔːr ən ˈaʊər baɪ ðɛn/', 'Mesma forma, com foco na espera que continua.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-09', 'lesson-grammar-b2-08', 9, 'sentence', 'He will probably have forgotten about it by tomorrow.', 'Ele provavelmente já terá esquecido isso até amanhã.', '/hiː wɪl ˈprɑːbəbli hæv fərˈɡɑːtən əˈbaʊt ɪt baɪ təˈmɑːroʊ/', 'O advérbio fica entre "will" e "have".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"probably","pos":"adverb","ipa":"/ˈprɑːbəbli/","gloss":"provavelmente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"forgotten","pos":"verb","ipa":"/fərˈɡɑːtən/","gloss":"esquecido"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-grammar-b2-08-10', 'lesson-grammar-b2-08', 10, 'sentence', 'We will not have finished before noon.', 'Não teremos terminado antes do meio-dia.', '/wiː wɪl nɑːt hæv ˈfɪnɪʃt bɪˈfɔːr nuːn/', 'Negativa: "will not have" + particípio.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL)
